import numpy as np
def rd(p):
    lines=open(p).read().split('\n')
    n=int(lines[0]); syms=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); syms.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return syms,np.array(xyz)
s,P=rd('complex_raw.xyz')
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Ru':1.46}
n=len(s)
adj=[[] for _ in range(n)]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(P[i]-P[j])
        if d < 1.25*(cov[s[i]]+cov[s[j]]):
            adj[i].append(j); adj[j].append(i)
seen=set(); frags=[]
for i in range(n):
    if i in seen: continue
    st=[i]; comp=[]
    while st:
        k=st.pop()
        if k in seen: continue
        seen.add(k); comp.append(k); st+=adj[k]
    frags.append(comp)
for f in frags:
    print("frag size",len(f),"mass",round(sum({'H':1.008,'C':12.011,'N':14.007,'P':30.974,'Ru':101.07}[s[i]] for i in f),2))
    if len(f)<69: print(" members(0-based):",f,[s[i] for i in f])
